#pragma once
// Boot splash: one of the penguins in boot_sprite.h (random per boot) goes "noot noot" — his beak
// turns into a trumpet / O-lips twice. No text.
// Non-blocking: update() does one small drawing step per call, so loop(), the LED heartbeat and
// the watchdog keep running while it plays. Canonical in firmware/controller/; tests/11_ui_dev has a copy.
// Sprites are generated by tools/sprites/make_pingu.py.
#include <Adafruit_ST7789.h>
#include "boot_sprite.h"

class BootSplash {
 public:
  void begin(Adafruit_ST7789 *t, uint16_t w, uint16_t h, uint8_t which, uint32_t now) {
    tft = t;
    W = w;
    H = h;
    sp = &SPLASH_SPRITES[which % SPLASH_COUNT];
    S = 4;
    while (S > 1 && (sp->w * S > W - 8 || sp->h * S > H - 8)) S--;
    sx = (W - sp->w * S) / 2;
    sy = (H - sp->h * S) / 2;
    step = BG;
    strip = 0;
    at = now;
  }

  bool active() const { return step != DONE; }

  // Returns true once the splash has finished and the screen is black again.
  bool update(uint32_t now) {
    switch (step) {
      case BG:      // background in strips (a full fill is ~0.5 s at 2 MHz)
        if (fillStrip(sp->bg)) {
          step = SPRITE;
          idx = ry = 0;
        }
        break;
      case SPRITE:  // 6 sprite rows per call
        if (blit(sp->base, sx, sy, sp->w, sp->h, 6)) {
          step = ANIM;
          stage = 0;
          at = now;
        }
        break;
      case ANIM:
        anim(now);
        break;
      case CLEAR:   // back to black for the dashboard
        if (fillStrip(0x0000)) step = DONE;
        break;
      case DONE:
        break;
    }
    return step == DONE;
  }

 private:
  enum Step : uint8_t { BG, SPRITE, ANIM, CLEAR, DONE };
  Adafruit_ST7789 *tft;
  const SplashSprite *sp;
  uint16_t W, H, strip;
  uint8_t S;
  int16_t sx, sy;
  Step step = DONE;
  uint16_t idx;
  uint8_t ry, stage;
  uint32_t at;

  bool fillStrip(uint16_t c) {
    tft->fillRect(0, strip, W, 24, c);
    strip += 24;
    if (strip < H) return false;
    strip = 0;
    return true;
  }

  uint16_t color(uint8_t c) const { return c ? pgm_read_word(sp->pal + c) : sp->bg; }

  // Streams up to `rows` sprite rows (from where the last call stopped) through ONE address window:
  // one CASET/RASET/RAMWR, then pixels. Each sprite row is replayed S times for the vertical scale.
  // (Drawing every colour run as its own fillRect cost ~50 window commands per beak patch; a mangled
  // command then shows up as thin streaks or mirrored fragments.) True when all h rows are done.
  bool blit(const uint8_t *data, int16_t ox, int16_t oy, uint8_t w, uint8_t h, uint8_t rows) {
    if (ry + rows > h) rows = h - ry;
    tft->startWrite();
    tft->setAddrWindow(ox, oy + ry * S, w * S, rows * S);
    for (uint8_t r = 0; r < rows; r++, ry++) {
      uint16_t rowStart = idx;
      for (uint8_t k = 0; k < S; k++) {
        idx = rowStart;
        for (uint8_t x = 0; x < w;) {
          uint8_t b = pgm_read_byte(data + idx++);
          uint8_t n = (b & 0x0F) + 1;
          tft->writeColor(color(b >> 4), (uint32_t)n * S);
          x += n;
        }
      }
    }
    tft->endWrite();
    return ry >= h;
  }

  void beak(bool noot) {
    idx = ry = 0;
    blit(noot ? sp->noot : sp->beak, sx + sp->px * S, sy + sp->py * S, sp->pw, sp->ph, sp->ph);
  }

  // Timeline (ms after the sprite is up): noot 600, back 1000, noot 1250, back 1650, end 2600.
  void anim(uint32_t now) {
    static const uint16_t T[] = {600, 1000, 1250, 1650, 2600};
    if (stage >= 5 || now - at < T[stage]) return;
    if (stage == 4) {
      step = CLEAR;
      strip = 0;
    } else {
      beak(stage == 0 || stage == 2);
    }
    stage++;
  }
};
